742		simd_m2range16x16_inpl(&(v[ 32 ]), &(m2r[ 32 ]));
743	
744		simd_advance16x16_inpl(&(v[ 48 ]),   adv       );
745		simd_m2range16x16_inpl(&(v[ 48 ]), &(m2r[ 48 ]));
746	}
