706	/*-----------------------------------------
707	 * is 64x16 wide SIMD array all zeroes?
708	 *
709	 * SECURITY NOTE: tmp[] is scratch which caller MUST wipe
710	 * NOTE: DESTROYS ORIGINAL INPUTS
711	 */
712	static inline
713	REALLY_FORCE_INLINE
714	/**/
715	unsigned int simd_is_all0x64x16_inpl(uint16_t v[static 64],
716	                                   uint16_t tmp[static 16])
717	{
718		simd_or16x16(tmp, &(v[32]), &(v[48]));       // 2 3
719		simd_or16x16(v,     v,      &(v[16]));       // 0 1
720		simd_or16x16(v,     tmp,      v     );       // 0 1 2 3
721	
722		return simd_is_all0(v);
723	}
